/* prog51_union_find.c
 *
 * Re‑implementation of the original program (observed via reverse‑engineering).
 * The program implements a tiny disjoint‑set (union‑find) structure for the
 * elements 0 … 9 and processes commands given on the command line.
 *
 * Behaviour (as seen from the original binary):
 *
 *   * If no command line arguments are supplied (argc < 2) the program prints
 *     "NOOP" and exits.
 *
 *   * The program recognises three one‑letter commands (case‑sensitive):
 *
 *         U a b   – union the sets containing a and b.
 *                   Prints:  UNION a b
 *
 *         F a     – find the representative (root) of a.
 *                   Prints:  FIND a=root
 *
 *         C a b   – check whether a and b are in the same set.
 *                   Prints:  YES   (if same set)
 *                           NO    (otherwise)
 *
 *   * All element numbers must be decimal integers in the range 0 … 9.
 *     If a number is out of range, or if there are not enough arguments for a
 *     command, the program prints "INVALID" and stops processing further
 *     commands.
 *
 *   * The implementation uses path compression and union‑by‑rank, exactly as
 *     the original binary does.
 *
 *   * The program never prints anything else.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ELEM 10

static int parent[MAX_ELEM];
static int rankv[MAX_ELEM];

/* initialise the disjoint‑set structure */
static void dsu_init(void)
{
    for (int i = 0; i < MAX_ELEM; ++i) {
        parent[i] = i;
        rankv[i] = 0;
    }
}

/* find with path compression */
static int dsu_find(int x)
{
    if (parent[x] != x)
        parent[x] = dsu_find(parent[x]);
    return parent[x];
}

/* union by rank, prints the required message */
static void dsu_union(int a, int b)
{
    int ra = dsu_find(a);
    int rb = dsu_find(b);
    if (ra == rb) {
        /* still print the UNION line as the original binary does */
        printf("UNION %d %d\n", a, b);
        return;
    }
    if (rankv[ra] < rankv[rb]) {
        parent[ra] = rb;
    } else {
        parent[rb] = ra;
        if (rankv[ra] == rankv[rb])
            ++rankv[ra];
    }
    printf("UNION %d %d\n", a, b);
}

static int valid_index(long v)
{
    return v >= 0 && v < MAX_ELEM;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    dsu_init();

    int idx = 1;
    while (idx < argc) {
        char cmd = argv[idx][0];
        if (cmd == 'U') {                     /* UNION command */
            if (idx + 2 >= argc) {            /* not enough numbers */
                puts("INVALID");
                break;
            }
            char *endptr;
            long a = strtol(argv[idx + 1], &endptr, 10);
            if (*endptr != '\0') { puts("INVALID"); break; }
            long b = strtol(argv[idx + 2], &endptr, 10);
            if (*endptr != '\0') { puts("INVALID"); break; }
            if (!valid_index(a) || !valid_index(b)) { puts("INVALID"); break; }
            dsu_union((int)a, (int)b);
            idx += 3;
        } else if (cmd == 'F') {                /* FIND command */
            if (idx + 1 >= argc) { puts("INVALID"); break; }
            char *endptr;
            long a = strtol(argv[idx + 1], &endptr, 10);
            if (*endptr != '\0') { puts("INVALID"); break; }
            if (!valid_index(a)) { puts("INVALID"); break; }
            int root = dsu_find((int)a);
            printf("FIND %ld=%d\n", a, root);
            idx += 2;
        } else if (cmd == 'C') {                /* CONNECTED / CHECK command */
            if (idx + 2 >= argc) { puts("INVALID"); break; }
            char *endptr;
            long a = strtol(argv[idx + 1], &endptr, 10);
            if (*endptr != '\0') { puts("INVALID"); break; }
            long b = strtol(argv[idx + 2], &endptr, 10);
            if (*endptr != '\0') { puts("INVALID"); break; }
            if (!valid_index(a) || !valid_index(b)) { puts("INVALID"); break; }
            if (dsu_find((int)a) == dsu_find((int)b))
                puts("YES");
            else
                puts("NO");
            idx += 3;
        } else {
            puts("INVALID");
            break;
        }
    }
    return 0;
}
